// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // Ensure burnAmount does not exceed initial supply (0) so we need to mint first
        vm.assume(burnAmount > 0 && burnAmount <= 1000000);
        c.mintToken(address(this), burnAmount);
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        c.burn(burnAmount);
        uint256 totalSupplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));
        // General rule: totalSupply decreases by burnAmount, balance decreases by burnAmount
        assertTrue(totalSupplyAfter == totalSupplyBefore - burnAmount && balanceAfter == balanceBefore - burnAmount);
    }
}

