// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount, address burner) public {
        vm.assume(burner != address(0));
        vm.assume(burnAmount <= type(uint256).max);
        // give burner some tokens and set owner
        c.mintToken(burner, burnAmount);
        vm.prank(c.owner());
        c.mintToken(burner, burnAmount);
        // compute totalSupply before burn
        uint256 totalBefore = c.totalSupply();
        // compute sum of all balances before burn (simplified: only burner has balance)
        uint256 sumBalancesBefore = c.balanceOf(burner);
        // ensure burner is not frozen
        vm.prank(c.owner());
        c.freezeAccount(burner, false);
        // perform burn
        vm.prank(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        if (!success) {
            // burn reverted, state unchanged
            assertTrue(c.totalSupply() == totalBefore && c.balanceOf(burner) == sumBalancesBefore);
        } else {
            // burn succeeded: totalSupply decreased by burnAmount, balance decreased by burnAmount
            uint256 totalAfter = c.totalSupply();
            uint256 balanceAfter = c.balanceOf(burner);
            // The invariant: totalSupply equals the sum of all balances (only burner has tokens)
            // In the buggy version, totalSupply increases, breaking this
            assertTrue(totalAfter == balanceAfter);
        }
    }
}

