pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 mintAmount, uint256 burnValue) public {
        // Restrict inputs to avoid overflow and ensure valid state
        vm.assume(initialSupply > 0 && initialSupply < 1e30);
        vm.assume(mintAmount < 1e30);
        vm.assume(burnValue > 0 && burnValue <= initialSupply + mintAmount);

        // Re-deploy with desired initial supply
        c = new C(initialSupply, "", "");

        // Mint tokens to owner for burning
        c.mintToken(address(this), mintAmount);

        // Record totalSupply before burn
        uint256 totalSupplyBefore = c.totalSupply();

        // Perform burn
        c.burn(burnValue);

        // General rule: after burn, totalSupply equals (totalSupplyBefore - burnValue)
        // In reference: totalSupply = totalSupplyBefore - burnValue
        // In buggy: totalSupply = totalSupplyBefore (no decrement)
        assertTrue(c.totalSupply() == totalSupplyBefore - burnValue, "totalSupply should decrease by burn amount");
    }
}

