pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address burner, uint256 amount) public {
        vm.assume(burner != address(0));
        amount = bound(amount, 1, 1000000);
        // Mint tokens to burner so burn is possible
        c.mintToken(burner, amount);
        // Record balance before burn
        uint256 balanceBefore = c.balanceOf(burner);
        // Attempt burn from burner
        vm.prank(burner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", balanceBefore));
        // Note: onlyOwner check prevents non-owner from burning, but we don't care about revert path
        // We just need that totalSupply after any call respects the invariant
        // For the property, we check that totalSupply is at least each balanceOf entry
        // We test with the burner's address
        uint256 total = c.totalSupply();
        uint256 bal = c.balanceOf(burner);
        // The invariant: totalSupply >= balanceOf[any address] (here burner)
        // This holds on reference because totalSupply tracks sum of balances, but on buggy version
        // mintToken increases balanceOf without increasing totalSupply, so after burn totalSupply < balanceOf
        assertTrue(total >= bal, "totalSupply should be >= each balance");
    }
}

