pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnAmount) public {
        vm.assume(caller != address(0));
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= 1000000);
        vm.deal(caller, 1 ether);

        // Set up initial balance by minting
        vm.prank(c.owner());
        c.mintToken(caller, burnAmount * 2);

        uint256 initialBalance = c.balanceOf(caller);
        require(initialBalance >= burnAmount, "Not enough balance");

        uint256 initialTotalSupply = c.totalSupply();

        // Execute burn
        vm.prank(caller);
        bool success = c.burn(burnAmount);

        // General rule: burn reduces caller's balance by _value and reduces totalSupply by same
        assertTrue(success && c.balanceOf(caller) == initialBalance - burnAmount && c.totalSupply() == initialTotalSupply - burnAmount);
    }
}

