import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 value, address anyAccount) public {
        vm.assume(anyAccount != address(0));
        vm.assume(value <= c.balanceOf(caller())); // ensure caller has enough balance
        // Record frozenAccount state before burn
        bool frozenBefore = c.frozenAccount(anyAccount);
        // Setup caller and execute burn
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));
        if (success) {
            bool frozenAfter = c.frozenAccount(anyAccount);
            assertTrue(frozenBefore == frozenAfter, "frozenAccount changed after burn");
        } else {
            // burn reverted; state unchanged
            bool frozenAfter = c.frozenAccount(anyAccount);
            assertTrue(frozenBefore == frozenAfter, "frozenAccount changed after burn revert");
        }
    }
}

