pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address attacker, uint256 burnAmount, address frozenTarget) public {
        // Restrict to a valid non-zero frozen target to check
        vm.assume(frozenTarget != address(0));
        // Freeze an arbitrary account
        vm.prank(c.owner());
        c.freezeAccount(frozenTarget, true);
        // Record frozen state before burn
        bool frozenBefore = c.frozenAccount(frozenTarget);
        // Attempt burn as caller (anyone)
        vm.prank(attacker);
        // The burn may revert; we handle that
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.burn.selector, burnAmount));
        // Check the rule: if burn succeeded, frozenAccount of frozenTarget must be unchanged
        if (success) {
            assertTrue(c.frozenAccount(frozenTarget) == frozenBefore);
        } else {
            // If it reverted, the property is vacuously true
            assertTrue(true);
        }
    }
}

