pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 _value) public {
        // Ensure the owner has enough balance to burn
        vm.assume(_value > 0 && _value <= c.balanceOf(address(this)));

        // Record totalSupply before burn
        uint256 supplyBefore = c.totalSupply();

        // Perform burn from the owner account
        c.burn(_value);

        // General rule: totalSupply decreases by exactly _value
        assertTrue(c.totalSupply() == supplyBefore - _value);
    }
}

